// computation kernel
// A: i x j
// u1,u2,w,x,z: i
// v1,v2,y: j
//
// Optimized version:
// - keeps A row-major (inner 'j') for good locality in rank-2 update and final GEMV
// - introduces two temporary vectors:
//     y_beta[j]  = beta * y[j]
//     x_alpha[j] = alpha * x[j]
//   reducing the number of multiplications by alpha/beta from O(N²) to O(N)
// - performs scalar replacement where possible (keep u1[i], u2[i], w[i] in registers)
// - preserves the original mathematical semantics
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	// Problem size (square matrix, so |i| == |j|)
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// --------------------------------------------------------------------
	// Temporary scaled vectors (length N, dimension 'j'):
	//   y_beta[j]  = beta * y[j]
	//   x_alpha[j] = alpha * x[j]
	// Extra memory is O(N), negligible compared to O(N²) for A.
	// --------------------------------------------------------------------
	auto len_j = set_length<'j'>(n_j);

	auto y_beta_bag  = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ len_j);
	auto x_alpha_bag = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ len_j);

	// Work with copyable, non-owning reference bags inside lambdas
	auto y_beta  = y_beta_bag.get_ref();
	auto x_alpha = x_alpha_bag.get_ref();

	#pragma scop

	// --------------------------------------------------------------------
	// 1) Rank-2 update:
	//      A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j]
	//
	// We traverse A row-wise (i outer, j inner). For each row i we hoist
	// u1[i] and u2[i] into scalars, so the inner j-loop only touches A
	// and v1/v2, improving cache locality and reducing loads.
	// --------------------------------------------------------------------
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto trav_i) {
		// state_i contains only the index in 'i' for this row
		auto state_i = trav_i.state();

		// scalar replacement: keep u1[i] and u2[i] in registers
		const num_t u1_i = u1[state_i];
		const num_t u2_i = u2[state_i];

		// now stream across columns j of this row
		trav_i.template for_each<'j'>([=](auto state) {
			A[state] = A[state]
			         + u1_i * v1[state]
			         + u2_i * v2[state];
		});
	});

	// --------------------------------------------------------------------
	// 2a) Precompute y_beta[j] = beta * y[j]
	// --------------------------------------------------------------------
	traverser(y, y_beta).for_each([=](auto state) {
		y_beta[state] = beta * y[state];
	});

	// --------------------------------------------------------------------
	// 2b) x[i] = x[i] + sum_j A[j,i] * y_beta[j]
	//
	// This is equivalent to the original:
	//    x[i] += beta * A[j,i] * y[j]
	// since y_beta[j] = beta * y[j], and x was initialized to 0.
	//
	// We reuse the transposed logical view A_T so that A_T[i,j] == A[j,i],
	// but we now avoid multiplying by beta in the inner loop.
	// We also accumulate into a scalar 'acc' per i to keep x[i] in a register.
	// --------------------------------------------------------------------
	auto A_T = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

	traverser(A_T, x, y_beta).template for_dims<'i'>([=](auto trav_i) {
		// index in 'i' for this reduction
		auto state_i = trav_i.state();
		num_t acc = x[state_i]; // starts at 0 from init_array

		trav_i.template for_each<'j'>([=, &acc](auto state) {
			// state has both 'i' and 'j':
			//   A_T[state] = A[j,i]
			//   y_beta[state] depends only on 'j'
			acc += A_T[state] * y_beta[state];
		});

		x[state_i] = acc;
	});

	// --------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i]
	// simple element-wise vector addition
	// --------------------------------------------------------------------
	traverser(x, z).for_each([=](auto state) {
		x[state] = x[state] + z[state];
	});

	// --------------------------------------------------------------------
	// 4a) Precompute x_alpha[j] = alpha * x[j]
	//
	// x is indexed by 'i'; we create a view x_j where the logical index
	// is called 'j', to match the 'j' dimension used together with A.
	// --------------------------------------------------------------------
	auto x_j = x ^ noarr::rename<'i', 'j'>();

	traverser(x_j, x_alpha).for_each([=](auto state) {
		x_alpha[state] = alpha * x_j[state];
	});

	// --------------------------------------------------------------------
	// 4b) w[i] = w[i] + sum_j A[i,j] * x_alpha[j]
	//
	// This is equivalent to the original
	//     w[i] += alpha * A[i,j] * x[j]
	// but with alpha pulled out into x_alpha[j] = alpha * x[j].
	//
	// We traverse A row-wise (i outer, j inner). For each row i we keep
	// the running sum for w[i] in a scalar 'acc', touching w[i] only once.
	// --------------------------------------------------------------------
	traverser(A, w, x_alpha).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		num_t acc = w[state_i]; // starts at 0 from init_array

		trav_i.template for_each<'j'>([=, &acc](auto state) {
			// state has 'i' and 'j':
			//   A[state] is A[i,j] in row-major order
			//   x_alpha[state] depends only on 'j'
			acc += A[state] * x_alpha[state];
		});

		w[state_i] = acc;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

