                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	// Tile sizes tuned for a modern multi-core CPU; feel free to adjust.
	// They are compile-time constants so the compiler can fully optimize
	// the blocked traversal.
	constexpr std::size_t tile_i = 64;
	constexpr std::size_t tile_j = 64;

	// Common 2D blocking used in the row-major phases that touch A.
	// - 'i' -> ('I', 'i', 's'): block index I, in-block index i, presence flag s
	// - 'j' -> ('J', 'j', 't'): block index J, in-block index j, presence flag t
	// The guard dimensions 's' and 't' are empty (length 0) for out-of-range
	// positions in the last, partial tiles, so we never access elements
	// beyond the logical N x N domain.
	auto block_ij =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 's'>(noarr::lit<tile_i>) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(noarr::lit<tile_j>);

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Rank-2 update:
	//    A[i,j] = A[i,j] + u1[i]*v1[j] + u2[i]*v2[j]
	// ------------------------------------------------------------------
	//
	// We iterate A in (I, i, J, j) tiles. Inside a fixed physical row
	// (given by the pair (I, i)), we keep u1[i] and u2[i] in registers
	// while streaming all columns j. This preserves the original GEMVER
	// semantics but improves cache locality and reduces redundant loads.
	traverser(A, u1, v1, u2, v2)
		.order(block_ij)
		.template for_dims<'I'>([&](auto trav_I) {
			// trav_I: one tile of rows (I fixed)

			// Iterate valid rows inside this row-tile. The presence
			// dimension 's' ensures that, in the last partial tile,
			// only rows within [0, N) are visited.
			trav_I.template for_dims<'i', 's'>([&](auto trav_row) {
				// trav_row: a single logical row i inside tile I
				auto row_state = trav_row.state(); // contains 'I', 'i', 's'

				// Scalar replacement: reuse u1[i] and u2[i] across all
				// columns j in this row.
				num_t u1_i = u1[row_state];
				num_t u2_i = u2[row_state];

				// Iterate all column tiles J and their in-tile indices j.
				trav_row.template for_dims<'J'>([&](auto trav_J) {
					// trav_J: (I, i, s, J) fixed, j/t vary
					trav_J.for_each([&](auto state) {
						// state: (I, i, s, J, j, t)
						// 't' is the column presence flag, so only valid
						// (i,j) pairs appear here.
						A[state] = A[state]
							+ u1_i * v1[state]
							+ u2_i * v2[state];
					});
				});
			});
		});

