	// 2) x[i] = x[i] + beta * A[j,i] * y[j]
	// ------------------------------------------------------------------
	//
	// We create a transposed *view* of A (no data movement):
	//   A_T[i,j] == A[j,i]
	// and then traverse it row-by-row: outer dimension 'j', inner 'i'.
	// This makes accesses to the underlying A row-major (contiguous in
	// memory) while preserving the original algebraic computation.
	auto A_T = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

	traverser(A_T, x, y).template for_dims<'j'>([&](auto trav_j) {
		// trav_j: one logical row of A_T, corresponding to one original
		// row j of A and a single y[j].

		auto row_state = trav_j.state();   // contains fixed 'j'
		num_t beta_yj = beta * y[row_state]; // == beta * y[j]

		// For this fixed j, update every x[i] using row A[j,*].
		trav_j.for_each([&](auto state) {
			// state: (i, j) for A_T
			// x[state] uses only 'i'; A_T[state] == A[j,i].
			x[state] = x[state] + beta_yj * A_T[state];
		});
	});

	// ------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i]
	// ------------------------------------------------------------------
	// Simple element-wise update; already perfectly contiguous in 'i'.
	traverser(x, z).for_each([&](auto state) {
		x[state] = x[state] + z[state];
	});

	// ------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i,j] * x[j]
	// ------------------------------------------------------------------
	//
	// We create a view of x indexed by 'j' so that its logical index
	// matches the column index of A. Then we reuse the same blocking
	// pattern as in step 1 and, for each physical row i, accumulate the
	// contribution to w[i] in a scalar before writing it back once.
	auto x_j = x ^ noarr::rename<'i', 'j'>();

	traverser(A, w, x_j)
		.order(block_ij)
		.template for_dims<'I'>([&](auto trav_I) {
			// trav_I: one tile of rows

			trav_I.template for_dims<'i', 's'>([&](auto trav_row) {
				// trav_row: one logical row i inside tile I
				auto row_state = trav_row.state();

				// Start from the current w[i] and accumulate into a
				// register across all columns j in all column-tiles J.
				num_t w_i = w[row_state];

				trav_row.template for_dims<'J'>([&](auto trav_J) {
					trav_J.for_each([&](auto state) {
						// state: (I, i, s, J, j, t)
						w_i += alpha * A[state] * x_j[state];
					});
				});

				// Store the updated value once per row.
				w[row_state] = w_i;
			});
		});

	#pragma endscop
}

