// computation kernel
// A: i x j
// u1,u2,w,x,z: i
// v1,v2,y: j
//
// Optimized version:
//
// - Step 1 (rank-2 update) keeps the i-outer / j-inner order, but hoists
//   u1[i] and u2[i] into scalars so they are loaded once per i, not per (i,j).
//
// - Step 2 precomputes y_beta[j] = beta * y[j] to avoid multiplying by beta
//   inside the O(N^2) loop, and traverses a transposed *view* of A in a
//   cache-friendly order (rows of A_T are contiguous).
//
// - Step 3 (x += z) remains a simple vector update.
//
// - Step 4 precomputes x_alpha[j] = alpha * x[j] so the final GEMV-like
//   step uses only A[i,j] * x_alpha[j]. It also accumulates w[i] in a
//   scalar register per i, reducing memory traffic.
//
// Extra storage is two N-length vectors (y_beta, x_alpha), i.e. O(N) extra
// memory, which is negligible compared to the O(N^2) matrix A.
[[gnu::flatten, gnu::noinline]]
void kernel_gemver(num_t alpha, num_t beta,
                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z,
                   auto y_beta, auto x_alpha) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
	//
	//    We keep the traversal order:
	//      for i:
	//        for j:
	//          A[i,j] += u1[i]*v1[j] + u2[i]*v2[j];
	//
	//    but hoist u1[i] and u2[i] into scalar temporaries so they are
	//    loaded once per row i instead of once per (i,j).
	// ------------------------------------------------------------------
	traverser(A, u1, v1, u2, v2).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has a fixed 'i'; collect that as a state suitable for u1/u2.
		auto state_i = trav_i.state(); // contains only 'i' from the original structure

		// Scalar replacement: keep u1[i], u2[i] in registers across the j-loop.
		num_t u1_i = u1[state_i];
		num_t u2_i = u2[state_i];

		trav_i.template for_each<'j'>([=](auto state) {
			// state has both 'i' and 'j'; it can index A and v1/v2.
			A[state] = A[state]
				+ u1_i * v1[state]
				+ u2_i * v2[state];
		});
	});

	// ------------------------------------------------------------------
	// 2a) Precompute y_beta[j] = beta * y[j]
	//
	//      This pulls the multiplication by beta out of the N^2 loop.
	// ------------------------------------------------------------------
	traverser(y, y_beta).for_each([=](auto state) {
		y_beta[state] = beta * y[state];
	});

	// ------------------------------------------------------------------
	// 2b) x[i] = x[i] + sum_j A[j,i] * y_beta[j]
	//
	//      We use a transposed *view* of A, created by renaming dimensions:
	//        A_T[i,j] == A[j,i]
	//
	//      A is stored row-major with inner dim 'j'. After renaming
	//      ('i' <-> 'j'), A_T has inner dim 'i', so iterating
	//      for_dims<'j'>(...).for_each<'i'> traverses rows of A_T
	//      (i.e., columns of A) contiguously in memory.
	//
	//      For each fixed j (row of A_T), we compute tmp = y_beta[j] once
	//      and reuse it for all i.
	// ------------------------------------------------------------------
	auto A_T = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

	traverser(A_T, x, y_beta).template for_dims<'j'>([=](auto trav_j) {
		// trav_j has 'j' fixed (one row of A_T, one element y_beta[j])
		auto state_j = trav_j.state(); // contains current 'j'
		num_t yb_j = y_beta[state_j];  // beta * y[j]

		// Now iterate i as the inner (and contiguous) dimension of A_T.
		trav_j.template for_each<'i'>([&](auto state) {
			// state has 'i' and 'j'; x uses 'i', A_T uses both.
			x[state] = x[state] + A_T[state] * yb_j;
		});
	});

	// ------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i];
	// ------------------------------------------------------------------
	traverser(x, z).for_each([=](auto state) {
		x[state] = x[state] + z[state];
	});

	// ------------------------------------------------------------------
	// 4a) Precompute x_alpha[j] = alpha * x[j]
	//
	//      x is indexed by 'i', but in the final GEMV we use x[j],
	//      so we create a 'j'-indexed view x_j and scale it into x_alpha.
	// ------------------------------------------------------------------
	auto x_j = x ^ noarr::rename<'i', 'j'>();

	traverser(x_j, x_alpha).for_each([=](auto state) {
		x_alpha[state] = alpha * x_j[state];
	});

	// ------------------------------------------------------------------
	// 4b) w[i] = w[i] + sum_j A[i][j] * x_alpha[j];
	//
	//      This corresponds to:
	//         w[i] += alpha * sum_j A[i,j] * x[j]
	//
	//      but with alpha pulled out by x_alpha[j] = alpha * x[j].
	//      A is row-major, so i-outer / j-inner is cache-friendly.
	//
	//      We also accumulate w[i] in a scalar register per i to avoid
	//      repeatedly loading/storing w[i] inside the inner loop.
	// ------------------------------------------------------------------
	traverser(A, w, x_alpha).template for_dims<'i'>([=](auto trav_i) {
		// Fix i and obtain a state that can index w[i].
		auto state_i = trav_i.state();

		// Scalar accumulator for w[i]
		num_t w_i = w[state_i];

		trav_i.template for_each<'j'>([&](auto state) {
			w_i += A[state] * x_alpha[state];
		});

		// Write back the accumulated value once per i
		w[state_i] = w_i;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// scalar parameters
	num_t alpha;
	num_t beta;

	// set lengths for dimensions
	auto len_i = noarr::set_length<'i'>(n);
	auto len_j = noarr::set_length<'j'>(n);

	// allocate bags (owning containers)

	// A: N x N, dims 'i' (rows) x 'j' (cols), row-major
	auto A  = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ len_i ^ len_j);

