	//   x_alpha[j] = alpha * x[j]
	// These are O(N) each and negligible compared to the O(N^2) matrix A.
	auto y_beta  = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ len_j);
	auto x_alpha = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ len_j);

	// initialize data
	init_array(alpha, beta,
	           A.get_ref(), u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	           w.get_ref(), x.get_ref(), y.get_ref(), z.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gemver(alpha, beta,
	              A.get_ref(), u1.get_ref(), v1.get_ref(), u2.get_ref(), v2.get_ref(),
	              w.get_ref(), x.get_ref(), y.get_ref(), z.get_ref(),
